CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT 'Brasil', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE games(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,genre TEXT NOT NULL,description TEXT NOT NULL,platforms TEXT NOT NULL);
CREATE TABLE teams(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,game_id INTEGER NOT NULL REFERENCES games(id),captain_id INTEGER NOT NULL REFERENCES users(id),description TEXT NOT NULL DEFAULT '');
CREATE TABLE team_members(team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(team_id,user_id));
CREATE TABLE tournaments(id INTEGER PRIMARY KEY,name TEXT NOT NULL,game_id INTEGER NOT NULL REFERENCES games(id),owner_id INTEGER NOT NULL REFERENCES users(id),capacity INTEGER NOT NULL CHECK(capacity BETWEEN 2 AND 64),team_size INTEGER NOT NULL CHECK(team_size BETWEEN 1 AND 8),starts_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','running','finished')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE registrations(id INTEGER PRIMARY KEY,tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,team_id INTEGER NOT NULL REFERENCES teams(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tournament_id,team_id));
CREATE TABLE registration_players(registration_id INTEGER NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(registration_id,user_id));
CREATE TABLE matches(id INTEGER PRIMARY KEY,tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,round INTEGER NOT NULL,position INTEGER NOT NULL,team_a INTEGER REFERENCES teams(id),team_b INTEGER REFERENCES teams(id),score_a INTEGER,score_b INTEGER,winner_id INTEGER REFERENCES teams(id),status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','ready','done','bye')),scheduled_at TEXT,stream_url TEXT NOT NULL DEFAULT '',UNIQUE(tournament_id,round,position));
CREATE TABLE posts(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,text TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE likes(post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(post_id,user_id));
CREATE TABLE comments(id INTEGER PRIMARY KEY,post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,text TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_matches_tournament ON matches(tournament_id,round,position);
CREATE INDEX idx_reg_players_user ON registration_players(user_id);
CREATE INDEX idx_posts_created ON posts(created_at);
